-- One slot. Draft only.
BEGIN;
-- PT103-S1-Q5
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT103-S1-Q5$batch01$ AND q.stimulus=$batch01$Attorneys for a criminal defendant charged that the government, in a coverup, had destroyed evidence that would have supported the defendant in a case. The government replied that there is no evidence that would even tend to support the defendant in the case.$batch01$ AND q.prompt=$batch01$Which one of the following is the most accurate evaluation of the government's reply?$batch01$ AND q.correct_choice=$batch01$A$batch01$) THEN RAISE EXCEPTION 'Question changed: PT103-S1-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT103-S1-Q5$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT103-S1-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S1-Q5$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$It leaves open the question of whether the government had destroyed such evidence.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S1-Q5 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S1-Q5$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$It establishes that the attorneys’ charge is an exaggeration.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S1-Q5 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S1-Q5$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$It shows that the attorneys did not know whether their charge was true.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S1-Q5 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S1-Q5$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$It demonstrates the government’s failure to search for evidence in its files.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S1-Q5 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S1-Q5$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$If true, it effectively disproves the charge made on behalf of the defendant.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S1-Q5 E'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT103-S1-Q5$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT103-S1-Q5$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT103-S1-Q5'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT103-S1-Q5$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Claim under dispute$batch01$, $batch01$The attorneys say the government destroyed evidence that would have helped the defendant.$batch01$), (1, $batch01$Government's reply$batch01$, $batch01$There is no evidence that would even tend to help the defendant.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$How could both statements be true? If the government destroyed the helpful evidence, none would remain now. “There is none” does not answer “Did you destroy it?” This is especially pointed because the alleged destruction would itself explain the absence the government cites.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the answer saying the reply leaves the destruction allegation unresolved.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT103-S1-Q5$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$The reply reports an absence of helpful evidence but does not establish how that absence arose. Destruction remains possible. A denial of the current evidence's existence is not a denial of the alleged earlier destruction.$batch01$), ($batch01$B$batch01$, $batch01$Calling the charge an exaggeration would require a reason to believe there was no destruction or that its scale was overstated. The reply provides neither.$batch01$), ($batch01$C$batch01$, $batch01$The attorneys could have information about destroyed material. The government's statement tells us nothing about what the attorneys know.$batch01$), ($batch01$D$batch01$, $batch01$There might be no evidence because a search found none, because none ever existed, or because it was destroyed. The reply alone does not prove a failure to search.$batch01$), ($batch01$E$batch01$, $batch01$Even if the reply is true *now*, it does not disprove that helpful evidence existed and was destroyed. The alleged coverup is a possible explanation for the reply's truth.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT103-S1-Q5$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
